query:
CREATE TABLE `collection_certificates` (
	`id` int AUTO_INCREMENT NOT NULL,
	`collectionId` int NOT NULL,
	`certificateId` int NOT NULL,
	`sortOrder` int NOT NULL DEFAULT 0,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	CONSTRAINT `collection_certificates_id` PRIMARY KEY(`id`)
);

CREATE TABLE `collections` (
	`id` int AUTO_INCREMENT NOT NULL,
	`userId` int NOT NULL,
	`name` varchar(200) NOT NULL,
	`description` text,
	`slug` varchar(150) NOT NULL,
	`isPublic` boolean NOT NULL DEFAULT false,
	`createdAt` timestamp NOT NULL DEFAULT (now()),
	`updatedAt` timestamp NOT NULL DEFAULT (now()) ON UPDATE CURRENT_TIMESTAMP,
	CONSTRAINT `collections_id` PRIMARY KEY(`id`)
);

ALTER TABLE `certificates` MODIFY COLUMN `fileUrl` text;
ALTER TABLE `certificates` MODIFY COLUMN `fileKey` text;
ALTER TABLE `certificates` ADD `skills` text;
ALTER TABLE `certificates` ADD `level` enum('beginner','intermediate','advanced','expert');
ALTER TABLE `certificates` ADD `category` enum('it','marketing','management','healthcare','other');
ALTER TABLE `certificates` ADD `priority` enum('normal','important') DEFAULT 'normal' NOT NULL;
ALTER TABLE `certificates` ADD `isVerified` boolean DEFAULT false NOT NULL;
ALTER TABLE `certificates` ADD `verificationUrl` text;
ALTER TABLE `certificates` ADD `externalUrl` text;

